//! gh#974 — `qp-active-set` failed a feasible convex QP carrying one
//! **consistent redundant equality row** (row = 2.5 × row 0) depending on
//! where that row sat: last, it returned `numerical_failure` at iteration 0
//! with `x = 0`; first, or dropped, it solved to the Clarabel optimum.
//!
//! ## The chain
//!
//! The cold homotopy reaches `t = 1` and hands its working set to
//! `solve_with_working_set`, whose `pin_working_set` factors the pinned KKT.
//! That working set pinned 14 rows, one more than the constraint block's
//! rank. The masked-rank guard in `factor_pinned_primal` reported it, the
//! prune kept 13 — and the retry's *own* masked-rank guard, at the shift that
//! retry settled at, found only 12 of those independent. The retry was single
//! shot, so its `?` surfaced a hard `LinearSolverFailure`, and `pounce-convex`
//! turned the hard error into `numerical_failure` with a zero-filled solution.
//! Row order matters only because it decides which row the rank test calls
//! dependent, and so which shift each factorization lands at.
//!
//! `cold_general_initial` had already been fixed for exactly this one-shot
//! retry (it loops while the subset shrinks), and `pin_working_set` now gets
//! the same loop. (PR #975 separately makes the homotopy fall back on the
//! error; this file runs on top of it, and
//! `pounce-qp/tests/issue974_pin_prune_loop.rs` is what pins the loop itself.)
//!
//! Seed 237 is the issue's second instance — `iteration_limit` on macOS arm64
//! at `main` 838feb9, `optimal` on 0.12.0. It solves on x86-64 Linux at both
//! commits, so it is carried here as a guard for platforms that reach the
//! failing trajectory, not as a reproduction of it.
//!
//! Data: `numpy.random.default_rng(seed)` exactly as in the issue's
//! reproduction, printed with `repr` so every digit is the generator's. `P` is
//! `l lᵀ`, the redundant row is built here as `2.5 * a[0]` (bit-identical to
//! numpy's), and `b` is numpy's own `A @ x0` over all rows. Oracle: Clarabel
//! 0.11.1, `-19.67063989646251` (seed 388) and `-22.16749000476421` (seed 237).

use pounce_convex::{
    ActiveSetOverrides, QpOptions, QpProblem, QpSolution, QpStatus, Triplet, solve_qp_active_set,
};
use pounce_feral::FeralSolverInterface;
use pounce_linsol::SparseSymLinearSolverInterface;

fn backend() -> Box<dyn SparseSymLinearSolverInterface> {
    Box::new(FeralSolverInterface::new())
}

fn active_set(p: &QpProblem) -> QpSolution {
    let mut mk = backend;
    solve_qp_active_set(
        p,
        &QpOptions::default(),
        &ActiveSetOverrides::default(),
        &mut mk,
    )
}

/// Row order of the equality block: the redundant row last (as generated),
/// first, or absent.
#[derive(Clone, Copy)]
enum Order {
    Last,
    First,
    Dropped,
}

#[allow(clippy::too_many_arguments)]
fn problem(
    l: &[f64],
    c: &[f64],
    a: &[&[f64]],
    b: &[f64],
    g: &[&[f64]],
    h: &[f64],
    order: Order,
) -> QpProblem {
    let n = c.len();
    let mut p_lower = Vec::new();
    for i in 0..n {
        for j in 0..=i {
            let v = l[i] * l[j];
            if v != 0.0 {
                p_lower.push(Triplet::new(i, j, v));
            }
        }
    }
    // Equality rows as generated: `a` then `2.5 * a[0]`, with `b` already
    // carrying the generator's own right-hand side for all of them.
    let redundant: Vec<f64> = a[0].iter().map(|v| 2.5 * v).collect();
    let mut rows: Vec<(&[f64], f64)> = a.iter().zip(b).map(|(r, &bi)| (*r, bi)).collect();
    rows.push((&redundant, b[a.len()]));
    match order {
        Order::Last => {}
        Order::First => rows.rotate_right(1),
        Order::Dropped => {
            rows.pop();
        }
    }
    let mut at = Vec::new();
    let mut bv = Vec::new();
    for (i, (r, bi)) in rows.iter().enumerate() {
        for (j, &v) in r.iter().enumerate() {
            if v != 0.0 {
                at.push(Triplet::new(i, j, v));
            }
        }
        bv.push(*bi);
    }
    // General rows, then the box `|x| <= 3` written as `G` rows.
    let mut gt = Vec::new();
    let mut hv = Vec::new();
    for (i, r) in g.iter().enumerate() {
        for (j, &v) in r.iter().enumerate() {
            if v != 0.0 {
                gt.push(Triplet::new(i, j, v));
            }
        }
        hv.push(h[i]);
    }
    let m = g.len();
    for j in 0..n {
        gt.push(Triplet::new(m + j, j, 1.0));
        hv.push(3.0);
    }
    for j in 0..n {
        gt.push(Triplet::new(m + n + j, j, -1.0));
        hv.push(3.0);
    }
    QpProblem {
        n,
        p_lower,
        c: c.to_vec(),
        a: at,
        b: bv,
        g: gt,
        h: hv,
        lb: vec![],
        ub: vec![],
    }
}

