fn seed237(order: Order) -> QpProblem {
    let a: Vec<&[f64]> = A237.iter().map(|r| r.as_slice()).collect();
    let g: Vec<&[f64]> = G237.iter().map(|r| r.as_slice()).collect();
    problem(&L237, &C237, &a, &B237, &g, &H237, order)
}

fn check(p: &QpProblem, want: f64, tag: &str) {
    let s = active_set(p);
    assert_eq!(s.status, QpStatus::Optimal, "{tag}: {:?}", s.status);
    assert!(
        (s.obj - want).abs() <= 1e-6 * want.abs(),
        "{tag}: obj {} vs {want}",
        s.obj
    );
}

#[test]
fn seed388_every_row_order_solves() {
    for (o, tag) in [
        (Order::Last, "last"),
        (Order::First, "first"),
        (Order::Dropped, "dropped"),
    ] {
        check(&seed388(o), -19.67063989646251, tag);
    }
}

#[test]
fn seed237_every_row_order_solves() {
    for (o, tag) in [
        (Order::Last, "last"),
        (Order::First, "first"),
        (Order::Dropped, "dropped"),
    ] {
        check(&seed237(o), -22.16749000476421, tag);
    }
}

